when.condition:
@{
            var prefix = context.Subscription.Id == "research-team-sub" ? "research" : "engineering";
            var userId = context.Request.Headers.GetValueOrDefault("x-demo-user-id", "");
            return !System.Text.RegularExpressions.Regex.IsMatch(userId, "^" + prefix + "-user-[12]$");
          }

@{
            var token = (Jwt)context.Variables["validated-jwt"];
            var tid = token.Claims.GetValueOrDefault("tid", "");
            var oid = token.Claims.GetValueOrDefault("oid", "");
            return tid.ToLowerInvariant() != "{{tenant-id}}".ToLowerInvariant()
              || !System.Text.RegularExpressions.Regex.IsMatch(oid, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$");
          }

set-variable.value:
@{
      var serviceId = context.Deployment.ServiceId ?? string.Empty;
      var markerIndex = serviceId.ToLowerInvariant().IndexOf("/providers/");
      return markerIndex > 0 ? serviceId.Substring(0, markerIndex) : string.Empty;
    }

@{
      var resourceGroupId = (string)context.Variables["resource-group-id"];
      var host = context.Api.ServiceUrl == null ? string.Empty : context.Api.ServiceUrl.Host;
      var dotIndex = host.IndexOf(".");
      var accountName = dotIndex > 0 ? host.Substring(0, dotIndex) : host;
      return string.IsNullOrEmpty(resourceGroupId) || string.IsNullOrEmpty(accountName)
        ? string.Empty
        : resourceGroupId + "/providers/Microsoft.CognitiveServices/accounts/" + accountName;
    }

@{
      var material = ((string)context.Variables["subject-tenant"]).ToLowerInvariant()
        + "|" + (string)context.Variables["subject-kind"]
        + "|" + ((string)context.Variables["subject-value"]).ToLowerInvariant();
      var key = Convert.FromBase64String("{{usage-hmac-key}}");
      var hmac = new System.Security.Cryptography.HMACSHA256(key);
      var digest = hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(material));
      hmac.Dispose();
      return Convert.ToBase64String(digest).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

outbound.log-to-eventhub:
@{
